create table if not exists public.catalogo_recetas_warrior_kids (
  codigo text primary key,
  id_receta bigint not null unique references public.recetas(id_receta) on delete cascade,
  nombre_platillo text not null,
  tipo_comida text not null check (tipo_comida in ('desayuno', 'colacion', 'comida', 'cena')),
  grupo_edad text not null,
  combinacion_grupos text not null,
  ingredientes text not null,
  porciones_por_grupo text not null,
  calorias_porcion_kcal integer not null check (calorias_porcion_kcal >= 0),
  tiempo_preparacion_min integer not null check (tiempo_preparacion_min >= 0),
  nota_educativa_app text not null,
  preparacion_completa text not null
);

alter table public.catalogo_recetas_warrior_kids enable row level security;
revoke all on public.catalogo_recetas_warrior_kids from anon, authenticated;
grant select on public.catalogo_recetas_warrior_kids to authenticated;

drop policy if exists catalogo_recetas_warrior_kids_lectura
  on public.catalogo_recetas_warrior_kids;
create policy catalogo_recetas_warrior_kids_lectura
  on public.catalogo_recetas_warrior_kids for select to authenticated
  using (true);

lock table public.recetas in share row exclusive mode;
create temporary table recipe_source (
  codigo text,
  nombre_platillo text,
  tipo_comida text,
  grupo_edad text,
  combinacion_grupos text,
  ingredientes text,
  porciones_por_grupo text,
  calorias_porcion_kcal integer,
  tiempo_preparacion_min integer,
  nota_educativa_app text,
  preparacion_completa text
);
insert into recipe_source (
  codigo, nombre_platillo, tipo_comida, grupo_edad, combinacion_grupos,
  ingredientes, porciones_por_grupo, calorias_porcion_kcal,
  tiempo_preparacion_min, nota_educativa_app, preparacion_completa
) values
  (E'R01', E'Huevo al comal con quelites y tortilla de maíz', E'desayuno', E'6 a 12 años', E'Alimentos de origen animal + Verduras + Cereales + Grasas', E'Huevo de rancho (1 pieza); Quintoniles o quelites de la zona (1 taza, limpios); Tortilla de maíz (2 piezas); Jitomate (1/4 pieza, picado); Cebolla (1 cucharada, picada); Aceite vegetal (1 cucharadita)', E'Alimentos de origen animal: 1; Verduras: 1; Cereales: 2; Grasas: 1', 285, 15, E'Los quelites son verdura de la sierra y el maíz aporta el cereal del plato.', E'Lava muy bien los quelites y pícalos finamente. En un comal o sartén con el aceite, acitrona la cebolla y el jitomate a fuego medio durante 2 minutos. Agrega los quelites y cocina 3 minutos más hasta que se suavicen. Aparta la verdura a un lado del sartén, bate el huevo e incorpóralo, revolviendo hasta que cuaje por completo (sin dejarlo crudo). Mezcla todo junto con la verdura. Sirve de inmediato acompañado de las tortillas de maíz calientes. Una persona adulta debe supervisar el uso del fuego y el manejo del huevo crudo.'),
  (E'R02', E'Molletes de frijol con queso de rancho', E'desayuno', E'6 a 12 años', E'Cereales + Leguminosas + Alimentos de origen animal + Verduras', E'Pan blanco o bolillo de la región (1 pieza); Frijol de la olla (1/2 taza); Queso fresco de rancho (30 gramos); Jitomate (1/4 pieza, picado); Cebolla (1 cucharada, picada)', E'Cereales: 2; Leguminosas: 1; Alimentos de origen animal: 1; Verduras: 1', 385, 15, E'El frijol es una leguminosa que también aporta fibra y proteína vegetal.', E'Corta el pan a la mitad a lo largo y retira un poco del migajón del centro. Unta el frijol de la olla sobre cada mitad, cubre con el queso desmoronado y hornea o calienta en el comal a fuego bajo de 5 a 8 minutos, hasta que el queso se derrita. Retira con cuidado (el pan estará caliente) y corona con el jitomate y la cebolla picados crudos. Una persona adulta debe manejar el horno o el comal.'),
  (E'R03', E'Hotcakes de avena y plátano macho', E'desayuno', E'6 a 12 años', E'Cereales + Frutas + Alimentos de origen animal + Leche y sustitutos + Azúcares', E'Avena en hojuelas (1/2 taza); Plátano macho maduro (1/2 pieza, machacado); Huevo (1 pieza); Leche de vaca (1/2 taza); Canela en polvo (al gusto); Miel de la región (1 cucharadita)', E'Cereales: 2; Frutas: 1; Alimentos de origen animal: 1; Leche y sustitutos: 1; Azúcares: 1', 465, 20, E'El plátano macho endulza de forma natural y suma una porción de fruta.', E'En un tazón mezcla la avena, el plátano macho machacado, el huevo, la leche y la canela hasta formar una pasta tersa. Calienta un comal o sartén antiadherente a fuego medio-bajo y, con ayuda de una persona adulta, vierte porciones pequeñas de la mezcla. Cocina de 2 a 3 minutos por lado, hasta que se doren y las burbujas de la superficie revienten. Sirve tibios con un hilo de miel de la región. Una persona adulta debe encargarse del volteo para evitar quemaduras.'),
  (E'R04', E'Atole de maíz con fruta de temporada', E'desayuno', E'6 a 8 años', E'Cereales + Leche y sustitutos + Frutas + Azúcares', E'Masa de maíz o maicena (3 cucharadas); Leche de vaca (1 taza); Fruta de temporada (guayaba, plátano o mango) (1/2 taza, picada); Piloncillo o azúcar (1 cucharadita)', E'Cereales: 1; Leche y sustitutos: 1; Frutas: 1; Azúcares: 1', 320, 15, E'El atole de maíz es una bebida tradicional de la región y aquí se endulza con fruta.', E'Disuelve la masa de maíz en un poco de leche fría hasta que no queden grumos. En una olla, calienta el resto de la leche a fuego medio sin dejar de mover. Incorpora la mezcla de masa disuelta y cocina, moviendo constantemente con una cuchara de madera, hasta que espese ligeramente (unos 6 a 8 minutos). Agrega el piloncillo y retira del fuego. Deja entibiar y sirve con la fruta picada encima. Una persona adulta debe manejar la olla caliente y el movimiento constante para que no se pegue.'),
  (E'R05', E'Quesadillas de flor de calabaza', E'desayuno', E'9 a 12 años', E'Cereales + Verduras + Alimentos de origen animal', E'Tortilla de maíz (2 piezas); Flor de calabaza (1 taza, limpia); Queso Oaxaca o queso fresco (40 gramos); Epazote (1 rama)', E'Cereales: 2; Verduras: 1; Alimentos de origen animal: 1', 265, 15, E'La flor de calabaza es verdura de la milpa y combina con el queso regional.', E'Lava la flor de calabaza y pícala junto con el epazote. Rellena las tortillas con el queso y la flor picada. Calienta un comal a fuego medio y cocina las quesadillas por ambos lados hasta que el queso se derrita y la tortilla se dore ligeramente, unos 3 minutos por lado. Una persona adulta debe supervisar el manejo del comal caliente.'),
  (E'R06', E'Sincronizadas de jamón de pavo y queso', E'desayuno', E'6 a 12 años', E'Cereales + Alimentos de origen animal + Verduras', E'Tortilla de harina (2 piezas); Jamón de pavo (30 gramos); Queso panela (30 gramos); Jitomate (1/4 pieza, en rodajas)', E'Cereales: 1; Alimentos de origen animal: 1; Alimentos de origen animal: 1; Verduras: 1', 270, 10, E'Combina cereal con dos porciones pequeñas de alimento de origen animal.', E'Coloca el jamón, el queso y el jitomate sobre una tortilla y cubre con la otra. Calienta en un comal a fuego medio de 2 a 3 minutos por lado, presionando ligeramente, hasta que el queso se derrita y la tortilla esté dorada. Corta en triángulos antes de servir. Una persona adulta debe supervisar el uso del comal.'),
  (E'R07', E'Mole de hongos de temporada con nopales', E'comida', E'9 a 12 años', E'Verduras + Cereales + Grasas', E'Hongos o setas silvestres de la región (1 taza); Nopal (1/2 taza, en cuadros); Chile guajillo o chipotle (1 pieza, sin semillas); Jitomate (1/2 pieza); Cebolla (1 cucharada); Tortilla de maíz (3 piezas); Aceite vegetal (1 cucharadita)', E'Verduras: 2; Cereales: 3; Grasas: 1', 305, 30, E'Los hongos silvestres son típicos de la Sierra Norte de Puebla en temporada de lluvias.', E'Limpia muy bien los hongos (retira tierra y restos) y córtalos en trozos medianos. Asa el chile, el jitomate y la cebolla en un comal 3 minutos, después licúa con un poco de agua hasta obtener una salsa tersa. En una olla con el aceite, sofríe la salsa colada 5 minutos a fuego medio. Agrega los hongos y el nopal, tapa y cocina 10 minutos más, moviendo de vez en cuando, hasta que los hongos estén suaves. Sirve caliente acompañado de las tortillas. Una persona adulta debe confirmar que los hongos sean de una especie comestible conocida antes de cocinarlos, y supervisar todo el uso del fuego.'),
  (E'R08', E'Pollo de rancho guisado con calabacitas y elote', E'comida', E'6 a 12 años', E'Alimentos de origen animal + Verduras + Cereales + Grasas', E'Pollo de rancho sin piel (100 gramos, en piezas); Calabacita (1/2 taza, en cubos); Elote (1/2 pieza, desgranado); Jitomate (1/2 pieza); Cebolla (1 cucharada); Arroz blanco (1/3 taza, cocido); Aceite vegetal (1 cucharadita)', E'Alimentos de origen animal: 2; Verduras: 2; Cereales: 1; Grasas: 1', 275, 40, E'El elote y la calabacita son verduras de milpa que se cultivan en la región.', E'Sazona las piezas de pollo con sal. En una cacerola con el aceite, dora el pollo por todos lados a fuego medio, unos 5 minutos. Retira y en el mismo aceite acitrona la cebolla y el jitomate picados. Regresa el pollo, agrega 1 taza de agua, la calabacita y el elote, tapa y cocina a fuego bajo de 20 a 25 minutos, hasta que el pollo esté bien cocido y las verduras suaves. Sirve con el arroz blanco. Una persona adulta debe verificar que el pollo esté completamente cocido antes de servir.'),
  (E'R09', E'Frijoles de la olla con epazote y tortilla', E'comida', E'6 a 8 años', E'Leguminosas + Cereales + Alimentos de origen animal', E'Frijol negro o bayo (3/4 taza, cocido); Epazote (1 rama); Cebolla (1 cucharada); Tortilla de maíz (3 piezas); Queso fresco (20 gramos, desmoronado)', E'Leguminosas: 2; Cereales: 3; Alimentos de origen animal: 1', 505, 15, E'El frijol con maíz forma una combinación completa de proteína vegetal, típica de la región.', E'Si los frijoles ya están cocidos, caliéntalos en una olla con el epazote y la cebolla picada a fuego bajo durante 10 minutos, machacando un poco con un cucharón para espesar el caldo. Sirve en un plato hondo, espolvorea el queso desmoronado por encima y acompaña con las tortillas calientes. Una persona adulta debe supervisar el manejo de la olla caliente.'),
  (E'R10', E'Pipián verde de pepita con pollo', E'comida', E'9 a 12 años', E'Grasas + Alimentos de origen animal + Verduras + Cereales', E'Pepita de calabaza verde (3 cucharadas); Pollo sin piel (100 gramos); Chile poblano (1/2 pieza, sin semillas); Tomate verde (3 piezas); Tortilla de maíz (3 piezas)', E'Grasas: 1; Alimentos de origen animal: 2; Verduras: 1; Cereales: 3', 415, 40, E'La pepita de calabaza es semilla de la milpa y espesa el guiso sin necesidad de más grasa.', E'Cuece el pollo en agua con un poco de cebolla hasta que esté bien cocido, unos 20 minutos; reserva el caldo. Tuesta la pepita en un comal sin aceite, moviendo constantemente para que no se queme, y muélela. Licúa el tomate verde y el chile poblano asado con un poco del caldo de pollo, cuela y cocina en una olla a fuego medio 5 minutos. Incorpora la pepita molida disuelta en caldo y el pollo deshebrado o en piezas, cocina 10 minutos más sin dejar de mover para que no se corte la salsa. Sirve con las tortillas. Una persona adulta debe supervisar el tostado de la pepita y el manejo del fuego.'),
  (E'R11', E'Ensalada de nopales con queso y aguacate', E'comida', E'6 a 12 años', E'Verduras + Alimentos de origen animal + Grasas', E'Nopal (1 taza, cocido y en cuadros); Jitomate (1/2 pieza); Cebolla morada (1 cucharada); Queso panela (30 gramos, en cubos); Aguacate (1/4 pieza); Cilantro (al gusto)', E'Verduras: 2; Alimentos de origen animal: 1; Grasas: 1', 195, 20, E'El nopal es verdura regional y el aguacate aporta grasa saludable.', E'Si el nopal no está cocido, hiérvelo en agua con un poco de sal de 8 a 10 minutos y enjuaga para quitar la baba. En un tazón mezcla el nopal, el jitomate, la cebolla, el queso y el aguacate en cubos. Agrega el cilantro picado y mezcla con cuidado para no deshacer el aguacate. Sirve fría o a temperatura ambiente. Una persona adulta debe supervisar el corte de los ingredientes.'),
  (E'R12', E'Caldo de habas con verdolagas', E'comida', E'6 a 8 años', E'Leguminosas + Verduras + Cereales', E'Haba seca (1/2 taza, remojada y cocida); Verdolaga (1 taza); Chile guajillo (1/2 pieza); Jitomate (1/4 pieza); Cebolla (1 cucharada); Tortilla de maíz (2 piezas)', E'Leguminosas: 1; Verduras: 1; Cereales: 2', 285, 35, E'Las habas y las verdolagas son cultivos comunes de traspatio en la sierra.', E'Si las habas ya están remojadas y cocidas, resérvalas. Licúa el chile asado con el jitomate y la cebolla, cuela y sofríe en una olla con un poco de agua durante 5 minutos. Agrega las habas y 2 tazas de agua, cocina a fuego medio 15 minutos. Añade la verdolaga limpia y cocina 5 minutos más, hasta que se suavice sin perder su color. Sirve caliente con las tortillas. Una persona adulta debe supervisar el remojo y cocción de las habas, y el manejo del fuego.'),
  (E'R13', E'Arroz rojo con verduras de la milpa', E'comida', E'6 a 12 años', E'Cereales + Verduras', E'Arroz blanco (1/2 taza, crudo); Zanahoria (1/4 taza, en cubos); Chícharo (2 cucharadas); Jitomate (1/2 pieza); Cebolla (1 cucharada); Aceite vegetal (1 cucharadita)', E'Cereales: 2; Verduras: 1', 255, 30, E'El arroz se cocina con poco aceite y las verduras suman color y fibra al plato.', E'Licúa el jitomate con la cebolla y cuela. En una olla con el aceite, fríe el arroz crudo 2 minutos moviendo constantemente hasta que cambie ligeramente de color. Agrega el licuado de jitomate y cocina 2 minutos más. Añade la zanahoria, el chícharo y 1 taza de agua caliente, tapa y cocina a fuego bajo 15 minutos sin destapar, hasta que el arroz esté suave y haya absorbido el líquido. Una persona adulta debe manejar el aceite caliente y el fuego.'),
  (E'R14', E'Quesadillas de requesón con quelites', E'cena', E'6 a 12 años', E'Cereales + Alimentos de origen animal + Verduras', E'Tortilla de maíz (2 piezas); Requesón o queso fresco (40 gramos); Quelites o espinaca (1 taza)', E'Cereales: 2; Alimentos de origen animal: 1; Verduras: 1', 265, 15, E'El requesón es un lácteo suave y fácil de digerir para la cena.', E'Lava y cocina los quelites al vapor 3 minutos, escurre bien. Rellena las tortillas con el requesón y los quelites, dobla por la mitad y cocina en un comal a fuego medio de 2 a 3 minutos por lado, hasta que se calienten por completo. Una persona adulta debe supervisar el comal caliente.'),
  (E'R15', E'Sopa de verduras con tortilla tostada', E'cena', E'6 a 12 años', E'Verduras + Cereales', E'Calabacita (1/4 taza); Zanahoria (1/4 taza); Chayote (1/4 taza); Jitomate (1/2 pieza); Tortilla de maíz (1 pieza, tostada y en trozos)', E'Verduras: 1; Cereales: 1', 95, 25, E'Una sopa ligera de verduras es una buena opción para la noche.', E'Licúa el jitomate con un poco de agua y cuela. En una olla, calienta el licuado y agrega 2 tazas de agua; cuando hierva, incorpora la calabacita, la zanahoria y el chayote cortados en cubos pequeños. Cocina a fuego medio de 12 a 15 minutos, hasta que las verduras estén suaves. Sirve caliente con los trozos de tortilla tostada encima. Una persona adulta debe supervisar el manejo de la olla caliente.'),
  (E'R16', E'Huevo revuelto con verdolagas y tortilla', E'cena', E'6 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Huevo (1 pieza); Verdolaga (1 taza); Cebolla (1 cucharadita); Tortilla de maíz (2 piezas)', E'Alimentos de origen animal: 1; Verduras: 1; Cereales: 2', 240, 15, E'Las verdolagas son ricas en fibra y se dan con facilidad en la región.', E'Lava bien las verdolagas y pícalas. En un sartén, acitrona la cebolla 1 minuto, agrega las verdolagas y cocina 3 minutos hasta que se suavicen. Incorpora el huevo batido y revuelve a fuego medio hasta que cuaje por completo. Sirve con las tortillas calientes. Una persona adulta debe supervisar el manejo del huevo crudo y el fuego.'),
  (E'R17', E'Tostadas de frijol con lechuga y jitomate', E'cena', E'6 a 12 años', E'Cereales + Leguminosas + Verduras + Alimentos de origen animal', E'Tostada horneada (2 piezas); Frijol refrito con poca grasa (1/3 taza); Lechuga (1/2 taza, picada); Jitomate (1/4 pieza); Queso fresco (20 gramos)', E'Cereales: 2; Leguminosas: 1; Verduras: 1; Alimentos de origen animal: 1', 340, 10, E'Los frijoles son leguminosas y también forman parte del Plato del Bien Comer.', E'Unta el frijol refrito sobre cada tostada horneada. Encima coloca la lechuga picada y el jitomate en cubos pequeños. Espolvorea el queso desmoronado al final. Sirve de inmediato para que la tostada no se humedezca. Una persona adulta puede ayudar a preparar el frijol refrito si aún no está listo.'),
  (E'R18', E'Picadillo de res con verduras de temporada', E'cena', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Carne molida de res magra (80 gramos); Zanahoria (1/4 taza); Papa (1/4 taza); Chícharo (2 cucharadas); Jitomate (1/2 pieza); Tortilla de maíz (2 piezas)', E'Alimentos de origen animal: 1; Verduras: 1; Cereales: 1', 150, 30, E'La carne magra aporta hierro, importante para el crecimiento.', E'Licúa el jitomate con un poco de agua y cuela. En un sartén, cocina la carne molida a fuego medio hasta que cambie de color, deshaciendo los grumos con una cuchara. Agrega el licuado de jitomate y cocina 3 minutos. Incorpora la papa y la zanahoria en cubos pequeños, tapa y cocina 10 minutos; añade el chícharo y cocina 5 minutos más, hasta que las verduras estén suaves. Sirve con las tortillas. Una persona adulta debe supervisar la cocción completa de la carne.'),
  (E'R19', E'Plátano macho horneado con canela', E'colacion', E'6 a 12 años', E'Frutas', E'Plátano macho maduro (1/2 pieza); Canela en polvo (al gusto)', E'Frutas: 1', 60, 15, E'El plátano macho es fruta de la región y se puede preparar sin azúcar añadida.', E'Precalienta el horno o comal a fuego medio. Corta el plátano macho a la mitad a lo largo, sin pelar, y colócalo con el corte hacia arriba. Espolvorea canela y hornea o cocina en comal de 10 a 12 minutos, hasta que esté suave y ligeramente dorado. Deja enfriar un poco antes de servir, ya que el centro queda muy caliente. Una persona adulta debe manejar el horno o comal.'),
  (E'R20', E'Palitos de jícama y pepino con limón', E'colacion', E'6 a 12 años', E'Verduras', E'Jícama (1/2 taza, en bastones); Pepino (1/2 taza, en bastones); Limón (al gusto); Chile piquín en polvo (opcional) (al gusto)', E'Verduras: 1', 25, 10, E'Una colación fresca y crujiente con una porción de verdura.', E'Lava, pela y corta la jícama y el pepino en bastones del tamaño de un dedo. Acomódalos en un plato y rocía con limón al gusto. El chile en polvo es opcional y puede omitirse si al niño no le gusta el picante. Una persona adulta debe supervisar el uso del cuchillo al cortar.'),
  (E'R21', E'Elote cocido con queso y limón', E'colacion', E'6 a 12 años', E'Cereales + Alimentos de origen animal', E'Elote (1 pieza, cocido); Queso fresco (2 cucharadas, desmoronado); Limón (al gusto)', E'Cereales: 1; Alimentos de origen animal: 1', 125, 25, E'El elote es cereal de la milpa y se disfruta mucho en la región.', E'Cuece el elote en agua con un poco de sal durante 15 a 20 minutos, hasta que esté suave. Escurre, deja entibiar un poco y unta el queso desmoronado por todo el elote; termina con unas gotas de limón. Una persona adulta debe supervisar la cocción y el manejo del elote caliente.'),
  (E'R22', E'Fruta de temporada con yogur natural', E'colacion', E'6 a 12 años', E'Frutas + Leche y sustitutos', E'Fruta de temporada (mandarina, plátano o guayaba) (1 taza, picada); Yogur natural sin azúcar (1/2 taza)', E'Frutas: 1; Leche y sustitutos: 1', 155, 5, E'Elegir fruta de temporada ayuda a que sea más fresca y económica.', E'Lava y pica la fruta de temporada en trozos pequeños. Sirve en un tazón y agrega el yogur natural por encima. Mezcla suavemente antes de servir. No requiere cocción.'),
  (E'R23', E'Palomitas naturales sin mantequilla', E'colacion', E'9 a 12 años', E'Cereales', E'Maíz palomero (3 cucharadas); Aceite vegetal (1 cucharadita); Sal (una pizca)', E'Cereales: 1', 70, 10, E'Las palomitas naturales son cereal integral cuando se preparan sin grasas añadidas en exceso.', E'En una olla con tapa, calienta el aceite a fuego medio y agrega 2 o 3 granos de maíz; cuando truenen, añade el resto del maíz, tapa y mueve la olla ocasionalmente. Cuando el tronido se espacie, retira del fuego. Deja reposar un minuto antes de destapar, pues puede quedar vapor caliente. Sazona con una pizca de sal. Una persona adulta debe manejar la olla caliente y el fuego en todo momento.'),
  (E'R24', E'Agua fresca de fruta de temporada sin azúcar añadida', E'colacion', E'6 a 12 años', E'Frutas', E'Fruta de temporada (guayaba, piña o sandía) (1 taza); Agua natural (2 tazas)', E'Frutas: 1', 60, 10, E'Es mejor beber agua natural con fruta que refrescos o jugos industrializados.', E'Licúa la fruta de temporada con el agua hasta que no queden grumos. Cuela si se desea una textura más ligera. Sirve fría. No se agrega azúcar; si hace falta dulzor, puede usarse un poco más de fruta madura. No requiere cocción.'),
  (E'R25', E'Camote horneado con un toque de miel', E'colacion', E'6 a 12 años', E'Cereales + Azúcares', E'Camote (1/2 pieza mediana); Miel de la región (1 cucharadita)', E'Cereales: 1; Azúcares: 1', 110, 45, E'El camote es un tubérculo de la región que se disfruta asado o al horno.', E'Lava bien el camote y pícalo varias veces con un tenedor. Hornea a 180°C durante 35 a 40 minutos, o cuécelo al vapor, hasta que esté suave al picarlo con un cuchillo. Córtalo a la mitad, deja enfriar un poco y rocía con la miel antes de servir. Una persona adulta debe manejar el horno y cortar el camote caliente.'),
  (E'R26', E'Ensalada de pollo deshebrado con verduras de la milpa', E'comida', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Grasas', E'Pechuga de pollo sin piel (100 gramos, cocida y deshebrada); Calabacita (1/4 taza, cocida); Zanahoria (1/4 taza, cocida); Chícharo (2 cucharadas, cocido); Lechuga (1/2 taza); Limón (al gusto); Aceite de oliva (1 cucharadita)', E'Alimentos de origen animal: 2; Verduras: 2; Grasas: 1', 205, 30, E'Se cuida la porción de cereal y se evita azúcar añadida, sin dejar de cubrir los demás grupos.', E'Cuece la pechuga en agua con un poco de cebolla hasta que esté bien cocida, deja enfriar y deshébrala. Cuece por separado la calabacita, la zanahoria y el chícharo al vapor 8 minutos. En un tazón mezcla el pollo deshebrado, las verduras cocidas y la lechuga cruda picada. Aliña con limón y el aceite de oliva justo antes de servir. Esta receta no debe usarse para restringir las calorías de un niño en crecimiento; la cantidad de cereal del día se ajusta en otro tiempo de comida, nunca quitándola por completo. Una persona adulta debe verificar que el pollo esté bien cocido.'),
  (E'R27', E'Pescado al vapor con verduras y tortilla de maíz', E'comida', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Filete de pescado blanco (100 gramos); Calabacita (1/4 taza); Zanahoria (1/4 taza); Limón (al gusto); Tortilla de maíz (2 piezas)', E'Alimentos de origen animal: 2; Verduras: 1; Cereales: 2', 245, 25, E'El pescado al vapor es una proteína de bajo contenido de grasa, útil cuando el especialista pide cuidar la grasa de la dieta.', E'Coloca el filete de pescado y las verduras en rebanadas dentro de una vaporera o, en su defecto, en una olla con una rejilla sobre agua hirviendo. Tapa y cocina de 10 a 12 minutos, hasta que el pescado se deshaga fácilmente con un tenedor y las verduras estén suaves. Sirve con un chorrito de limón y las tortillas de maíz calientes. Este plato no sustituye las indicaciones específicas de un médico o nutriólogo para diabetes o prediabetes; es solo una opción baja en grasa dentro del menú general. Una persona adulta debe verificar que el pescado esté bien cocido y revisar que no haya espinas.'),
  (E'R28', E'Avena con fruta de temporada sin azúcar añadida', E'desayuno', E'6 a 12 años', E'Cereales + Leche y sustitutos + Frutas', E'Avena en hojuelas (1/2 taza); Leche descremada o bebida vegetal sin azúcar (1 taza); Fruta de temporada (manzana o plátano) (1/2 taza, picada); Canela en polvo (al gusto)', E'Cereales: 2; Leche y sustitutos: 1; Frutas: 1', 295, 15, E'Esta versión no lleva azúcar añadida; el dulzor viene solo de la fruta.', E'En una olla pequeña, calienta la leche a fuego bajo. Agrega la avena y cocina, moviendo con frecuencia, de 5 a 7 minutos hasta que espese ligeramente. Retira del fuego, deja entibiar un poco y sirve con la fruta picada y canela encima. Una persona adulta debe supervisar el manejo de la olla caliente.'),
  (E'R29', E'Tlacoyos de frijol con queso y nopal', E'desayuno', E'9 a 12 años', E'Cereales + Leguminosas + Alimentos de origen animal + Verduras', E'Masa de maíz (1 taza); Frijol molido (1/2 taza); Queso fresco (30 gramos); Nopal (1/2 taza, cocido y picado); Salsa verde o roja suave (al gusto)', E'Cereales: 2; Leguminosas: 1; Alimentos de origen animal: 1; Verduras: 1', 340, 30, E'El tlacoyo es un antojito de maíz relleno de frijol, típico de muchas regiones de Puebla.', E'Mezcla la masa con un poco de agua hasta que esté manejable. Forma bolitas, haz un hueco en el centro y rellena con una cucharada de frijol molido; cierra y aplana dándole forma ovalada. Cocina en comal a fuego medio de 3 a 4 minutos por lado, hasta que la masa esté cocida y con unas manchitas doradas. Sirve con el nopal picado, el queso desmoronado y salsa suave encima. Una persona adulta debe supervisar el comal caliente.'),
  (E'R30', E'Huevos con rajas de chile poblano y elote', E'desayuno', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Huevo (1 pieza); Chile poblano (1/4 pieza, asado y en rajas); Elote (1/4 taza, desgranado); Cebolla (1 cucharada); Tortilla de maíz (2 piezas)', E'Alimentos de origen animal: 1; Verduras: 1; Cereales: 2', 240, 25, E'El chile poblano, en versión suave y sin semillas, aporta una verdura típica de la región.', E'Asa el chile poblano directo en la flama o comal hasta que la piel se ampolle, mételo en una bolsa de plástico 5 minutos para que sude, pela, desvena y corta en rajas delgadas (retira bien las semillas para que no pique fuerte). En un sartén, acitrona la cebolla, agrega el elote y las rajas, cocina 3 minutos. Incorpora el huevo batido y revuelve hasta que cuaje. Sirve con las tortillas. Una persona adulta debe asar y pelar el chile, y supervisar el manejo del fuego.'),
  (E'R31', E'Pan de fiesta de la región con queso fresco y fruta', E'desayuno', E'6 a 12 años', E'Cereales + Alimentos de origen animal + Frutas', E'Pan de fiesta o pan dulce regional (1 pieza pequeña); Queso fresco (20 gramos); Fruta de temporada (1/2 taza, picada)', E'Cereales: 1; Alimentos de origen animal: 1; Frutas: 1', 230, 10, E'El pan de fiesta es típico de las panaderías de Zacapoaxtla y la sierra.', E'Corta el pan a la mitad. Si se desea, calienta ligeramente en el comal 1 minuto por lado. Coloca el queso fresco desmoronado sobre una mitad y sirve acompañado de la fruta picada en un plato aparte. No requiere cocción adicional más que el calentado opcional del pan.'),
  (E'R32', E'Licuado de plátano con avena y cacahuate', E'desayuno', E'9 a 12 años', E'Frutas + Cereales + Leche y sustitutos + Grasas', E'Plátano (1 pieza); Avena en hojuelas (3 cucharadas); Leche de vaca (1 taza); Crema de cacahuate natural (1 cucharadita)', E'Frutas: 1; Cereales: 1; Leche y sustitutos: 1; Grasas: 1', 350, 5, E'El cacahuate se cultiva en varias zonas de Puebla y aporta grasas saludables en poca cantidad.', E'Licúa el plátano, la avena, la leche y la crema de cacahuate hasta obtener una mezcla tersa, aproximadamente 1 minuto. Sirve de inmediato en un vaso. No requiere cocción. Confirma siempre con el tutor si el niño tiene alergia al cacahuate antes de prepararlo.'),
  (E'R33', E'Tamal de elote dulce sencillo', E'desayuno', E'6 a 12 años', E'Cereales + Leche y sustitutos + Azúcares', E'Elote (2 piezas, desgranado); Mantequilla o manteca vegetal (1 cucharadita); Leche de vaca (1/4 taza); Piloncillo o azúcar (1 cucharadita); Hoja de elote (al gusto, para envolver)', E'Cereales: 2; Leche y sustitutos: 1; Azúcares: 1', 420, 70, E'El tamal de elote es un platillo tradicional que aprovecha el elote fresco de temporada.', E'Muele el elote desgranado junto con la leche hasta obtener una masa espesa. Mezcla con la mantequilla derretida y el piloncillo. Coloca una porción de masa en cada hoja de elote, dobla y amarra. Cocina al vapor en una vaporera durante 45 a 60 minutos, hasta que la masa se despegue fácilmente de la hoja. Deja enfriar un poco antes de servir, pues el centro queda muy caliente. Una persona adulta debe manejar la vaporera y el vapor caliente.'),
  (E'R34', E'Mixiotes sencillos de pollo con nopal', E'comida', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Pollo sin piel (100 gramos); Nopal (1/2 taza); Chile guajillo (1 pieza); Hoja de aguacate o laurel (1 pieza); Tortilla de maíz (2 piezas)', E'Alimentos de origen animal: 2; Verduras: 1; Cereales: 2', 275, 50, E'El mixiote es una forma tradicional de cocinar al vapor envuelto en una hoja o papel.', E'Remoja el chile guajillo en agua caliente 10 minutos, licúa con un poco de esa agua hasta obtener una salsa tersa. Marina el pollo y el nopal en la salsa junto con la hoja de aguacate. Envuelve en papel aluminio o en pencas si se tienen, formando paquetitos. Cocina al vapor en una vaporera durante 35 a 40 minutos, hasta que el pollo esté bien cocido. Sirve con las tortillas. Una persona adulta debe manejar el vapor caliente y verificar que el pollo esté completamente cocido.'),
  (E'R35', E'Chileatole de elote con pollo deshebrado', E'comida', E'6 a 12 años', E'Cereales + Alimentos de origen animal + Verduras', E'Elote (1 pieza, desgranado); Pollo cocido deshebrado (60 gramos); Chile poblano (1/4 pieza, asado); Epazote (1 rama); Masa de maíz (2 cucharadas)', E'Cereales: 1; Alimentos de origen animal: 1; Verduras: 1', 150, 30, E'El chileatole combina elote y chile en un caldo espeso típico de la sierra poblana.', E'Licúa el elote con un poco de agua y cuela. En una olla, disuelve la masa en un poco de agua aparte. Calienta el licuado de elote, agrega la masa disuelta y mueve constantemente para que no se pegue, cocina 10 minutos a fuego medio hasta que espese. Incorpora el chile poblano en rajas, el epazote y el pollo deshebrado, cocina 5 minutos más. Sirve caliente. Una persona adulta debe supervisar el manejo de la olla y el movimiento constante.'),
  (E'R36', E'Trucha de la sierra a la plancha con verduras', E'comida', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Filete de trucha (100 gramos); Calabacita (1/4 taza); Limón (al gusto); Ajo (1 diente, picado); Arroz blanco (1/3 taza, cocido)', E'Alimentos de origen animal: 2; Verduras: 1; Cereales: 1', 175, 25, E'La trucha se cría en varios ríos y criaderos de la Sierra Norte de Puebla.', E'Sazona el filete de trucha con sal, limón y ajo picado. Calienta una plancha o sartén con un mínimo de aceite y cocina el filete de 3 a 4 minutos por lado, hasta que la carne esté opaca y se deshaga con facilidad. Cuece la calabacita al vapor 8 minutos. Sirve el pescado con la calabacita y el arroz blanco. Una persona adulta debe verificar que el pescado esté bien cocido y revisar que no tenga espinas.'),
  (E'R37', E'Tinga de pollo con jitomate y chipotle suave', E'comida', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Pollo cocido deshebrado (100 gramos); Jitomate (1/2 pieza); Cebolla (2 cucharadas); Chile chipotle (1/4 pieza, sin semillas); Tostada horneada (2 piezas)', E'Alimentos de origen animal: 2; Verduras: 1; Cereales: 2', 275, 25, E'Usa muy poco chipotle para que el picante sea suave y apto para niños.', E'Licúa el jitomate con un trocito pequeño de chipotle (sin semillas) y cuela. En un sartén, acitrona la cebolla fileteada 3 minutos, agrega el licuado y cocina 5 minutos. Incorpora el pollo deshebrado y cocina 5 minutos más, hasta que se incorpore bien a la salsa. Sirve sobre las tostadas. Prueba la salsa antes de servir para confirmar que el picante sea leve; una persona adulta debe decidir la cantidad de chipotle según la tolerancia del niño.'),
  (E'R38', E'Caldo de pollo con verduras de la milpa', E'comida', E'6 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Pollo con hueso (150 gramos); Calabacita (1/4 taza); Zanahoria (1/4 taza); Elote (1/2 pieza); Chayote (1/4 taza); Arroz blanco (2 cucharadas, cocido)', E'Alimentos de origen animal: 2; Verduras: 2; Cereales: 1', 230, 45, E'Un caldo de pollo con varias verduras cubre buena parte del plato en un solo platillo.', E'Coloca el pollo en una olla con agua suficiente para cubrir, agrega sal y cocina a fuego medio 25 minutos, retirando la espuma que suba a la superficie. Agrega la zanahoria y el chayote en trozos, cocina 10 minutos más. Añade la calabacita y el elote en trozos, cocina 10 minutos adicionales, hasta que todas las verduras estén suaves y el pollo bien cocido. Sirve con el arroz. Una persona adulta debe retirar los huesos antes de dar el plato al niño y verificar que el pollo esté bien cocido.'),
  (E'R39', E'Enfrijoladas con queso y cebolla', E'comida', E'6 a 12 años', E'Cereales + Leguminosas + Alimentos de origen animal', E'Tortilla de maíz (3 piezas); Frijol negro molido (1/2 taza); Queso fresco (30 gramos); Cebolla (1 cucharada, picada)', E'Cereales: 3; Leguminosas: 1; Alimentos de origen animal: 1', 385, 20, E'Las enfrijoladas combinan tortilla y frijol, dos ingredientes base de la dieta regional.', E'Calienta el frijol molido con un poco de agua hasta que tenga consistencia de salsa espesa. Pasa cada tortilla por el frijol caliente para que se impregne bien, dobla en cuartos y acomoda en un plato. Espolvorea queso desmoronado y cebolla picada encima. Sirve tibio. Una persona adulta debe supervisar el manejo de la salsa caliente.'),
  (E'R40', E'Calabacitas rellenas de queso al horno', E'comida', E'9 a 12 años', E'Verduras + Alimentos de origen animal + Cereales', E'Calabacita (1 pieza grande); Queso Oaxaca o panela (30 gramos); Jitomate (1/4 pieza, picado); Elote (2 cucharadas, desgranado); Tortilla de maíz (2 piezas)', E'Verduras: 2; Alimentos de origen animal: 1; Cereales: 2', 290, 35, E'Rellenar verduras es una forma de que los niños coman más verdura sin notarlo tanto.', E'Corta la calabacita a la mitad a lo largo y, con una cuchara, retira un poco del centro para hacer espacio (resérvalo). Mezcla la pulpa retirada con el jitomate y el elote, rellena las calabacitas y corona con el queso. Hornea a 180°C durante 20 a 25 minutos, hasta que la calabacita esté suave y el queso derretido. Sirve con las tortillas. Una persona adulta debe manejar el horno.'),
  (E'R41', E'Lentejas guisadas con plátano macho y verduras', E'comida', E'6 a 12 años', E'Leguminosas + Frutas + Cereales', E'Lenteja (1/2 taza, cocida); Plátano macho maduro (1/4 pieza, en rodajas); Jitomate (1/2 pieza); Cebolla (1 cucharada); Tortilla de maíz (2 piezas)', E'Leguminosas: 1; Frutas: 1; Cereales: 2', 320, 30, E'El plátano macho frito o asado acompaña tradicionalmente los guisos de lenteja en varias regiones de México.', E'Si la lenteja ya está cocida, resérvala. Licúa el jitomate con la cebolla, cuela y sofríe en una olla 5 minutos. Agrega la lenteja y un poco de agua, cocina 10 minutos a fuego medio. Aparte, dora las rodajas de plátano macho en un sartén con muy poco aceite, 2 minutos por lado. Sirve la lenteja con el plátano encima y las tortillas. Una persona adulta debe supervisar el manejo del fuego y el aceite caliente.'),
  (E'R42', E'Sopa de hongos de temporada con epazote', E'comida', E'9 a 12 años', E'Verduras + Cereales', E'Hongos o setas silvestres (1 taza); Epazote (1 rama); Chile serrano (1/4 pieza, sin semillas); Cebolla (1 cucharada); Tortilla de maíz (2 piezas)', E'Verduras: 2; Cereales: 2', 190, 30, E'Los hongos de temporada son muy apreciados en la cocina de la Sierra Norte de Puebla.', E'Limpia muy bien los hongos retirando tierra y restos, córtalos en trozos. En una olla, sofríe la cebolla y el chile serrano picado muy fino 2 minutos. Agrega los hongos y cocina 5 minutos hasta que suelten su líquido. Añade 2 tazas de agua y el epazote, cocina 10 minutos más a fuego medio. Sirve caliente con las tortillas. Una persona adulta debe confirmar que los hongos sean de una especie comestible conocida antes de cocinarlos.'),
  (E'R43', E'Garbanzo guisado con verduras de temporada', E'comida', E'9 a 12 años', E'Leguminosas + Verduras + Cereales', E'Garbanzo (1/2 taza, cocido); Zanahoria (1/4 taza); Calabacita (1/4 taza); Jitomate (1/2 pieza); Tortilla de maíz (2 piezas)', E'Leguminosas: 1; Verduras: 1; Cereales: 2', 285, 30, E'El garbanzo es otra leguminosa que puede alternarse con el frijol durante la semana.', E'Licúa el jitomate con un poco de agua y cuela. En una olla, calienta el licuado 3 minutos, agrega la zanahoria en cubos y cocina 8 minutos. Añade la calabacita y el garbanzo cocido, cocina 8 minutos más, hasta que las verduras estén suaves. Sirve con las tortillas. Una persona adulta debe supervisar el manejo de la olla caliente.'),
  (E'R44', E'Milanesa de pollo al horno con ensalada', E'comida', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Pechuga de pollo (100 gramos, aplanada); Pan molido (2 cucharadas); Huevo (1/2 pieza, batida); Lechuga y jitomate (1 taza); Arroz blanco (1/3 taza, cocido)', E'Alimentos de origen animal: 2; Verduras: 1; Cereales: 1', 205, 35, E'Hornear en lugar de freír reduce la cantidad de grasa añadida al platillo.', E'Pasa la pechuga aplanada primero por el huevo batido y después por el pan molido, cubriendo bien ambos lados. Coloca en una charola con un poco de aceite en spray y hornea a 200°C de 18 a 20 minutos, volteando a la mitad del tiempo, hasta que esté dorada y bien cocida por dentro. Sirve con la ensalada de lechuga y jitomate y el arroz. Una persona adulta debe manejar el horno y verificar que el pollo esté completamente cocido.'),
  (E'R45', E'Ensalada de garbanzo con verduras frescas', E'comida', E'9 a 12 años', E'Leguminosas + Verduras + Grasas', E'Garbanzo (1/2 taza, cocido); Pepino (1/4 taza); Jitomate (1/4 pieza); Cebolla morada (1 cucharada); Aceite de oliva (1 cucharadita); Limón (al gusto)', E'Leguminosas: 1; Verduras: 1; Grasas: 1', 190, 15, E'Una opción fresca sin cereal extra, útil para variar la textura de los platillos de la semana.', E'Mezcla el garbanzo cocido y frío con el pepino, el jitomate y la cebolla morada, todo picado en cubos pequeños. Aliña con el aceite de oliva y limón al gusto justo antes de servir. No requiere cocción adicional. Una persona adulta debe supervisar el picado de los ingredientes.'),
  (E'R46', E'Memelitas de frijol con queso', E'cena', E'6 a 12 años', E'Cereales + Leguminosas + Alimentos de origen animal', E'Masa de maíz (1/2 taza); Frijol refrito (3 cucharadas); Queso fresco (20 gramos); Salsa suave (opcional) (al gusto)', E'Cereales: 2; Leguminosas: 1; Alimentos de origen animal: 1', 315, 20, E'Las memelas son más gruesas que la tortilla y se cocinan directo con el relleno encima.', E'Forma bolitas con la masa y aplánalas un poco más gruesas que una tortilla normal. Cocina en comal 2 minutos de un lado, voltea y, sobre el lado ya cocido, unta el frijol y pellizca ligeramente la orilla. Agrega el queso desmoronado encima y deja cocinar 2 minutos más, hasta que la masa esté bien cocida. Sirve con salsa suave si se desea. Una persona adulta debe supervisar el comal caliente.'),
  (E'R47', E'Crema de calabaza con un toque de elote', E'cena', E'6 a 12 años', E'Verduras + Cereales + Leche y sustitutos', E'Calabaza o calabacita (1 taza); Elote (1/4 taza, desgranado); Cebolla (1 cucharada); Leche descremada (1/4 taza)', E'Verduras: 1; Cereales: 1; Leche y sustitutos: 1', 190, 25, E'Una crema ligera es buena opción de cena, fácil de digerir antes de dormir.', E'Cuece la calabaza y el elote en agua con la cebolla durante 15 minutos, hasta que estén suaves. Licúa todo junto con la leche hasta obtener una crema tersa (con cuidado si se licúa caliente, dejar entibiar un poco y licuar por partes). Regresa a la olla y calienta 3 minutos más sin dejar hervir fuerte. Sirve tibia. Una persona adulta debe manejar la licuadora con líquido caliente.'),
  (E'R48', E'Tostadas de atún con verduras', E'cena', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Atún en agua (60 gramos, escurrido); Jitomate (1/4 pieza); Cebolla (1 cucharadita); Tostada horneada (2 piezas); Limón (al gusto)', E'Alimentos de origen animal: 1; Verduras: 1; Cereales: 2', 205, 10, E'El atún en agua es una opción práctica de proteína baja en grasa para la cena.', E'Mezcla el atún escurrido con el jitomate y la cebolla picados finamente, agrega limón al gusto. Reparte la mezcla sobre las tostadas horneadas justo antes de servir, para que no se humedezcan. No requiere cocción adicional.'),
  (E'R49', E'Quesadillas de huitlacoche', E'cena', E'9 a 12 años', E'Verduras + Cereales + Alimentos de origen animal', E'Huitlacoche (1/2 taza); Tortilla de maíz (2 piezas); Queso Oaxaca (30 gramos); Epazote (1 rama)', E'Verduras: 1; Cereales: 2; Alimentos de origen animal: 1', 265, 25, E'El huitlacoche es un hongo del maíz muy apreciado en la cocina mexicana tradicional.', E'Si el huitlacoche no está cocido, saltéalo en un sartén con muy poco aceite y el epazote picado durante 8 minutos, hasta que se vea brilloso y oscuro. Rellena las tortillas con el huitlacoche y el queso, cocina en comal de 2 a 3 minutos por lado, hasta que el queso se derrita. Una persona adulta debe supervisar el manejo del comal caliente.'),
  (E'R50', E'Esquites ligeros con limón', E'cena', E'6 a 12 años', E'Cereales', E'Elote (1 taza, desgranado); Epazote (1 rama); Limón (al gusto); Queso fresco (2 cucharadas, opcional)', E'Cereales: 2', 140, 20, E'Los esquites son una forma sencilla de comer elote cocido, sin necesidad de mucha grasa añadida.', E'Cuece los granos de elote en agua con el epazote durante 10 a 12 minutos, hasta que estén suaves. Escurre y sirve en un vaso o tazón con limón al gusto y, si se desea, un poco de queso desmoronado encima. Una persona adulta debe supervisar la cocción en agua caliente.'),
  (E'R51', E'Sopa de fideo con verduras', E'cena', E'6 a 12 años', E'Cereales + Verduras', E'Fideo (1/3 taza); Jitomate (1/2 pieza); Zanahoria (2 cucharadas); Chícharo (2 cucharadas); Cebolla (1 cucharada)', E'Cereales: 1; Verduras: 1', 140, 20, E'Una sopa sencilla y ligera, buena opción cuando la cena debe ser más pequeña que la comida.', E'Licúa el jitomate con la cebolla y cuela. En una olla con un poco de aceite, fríe el fideo 2 minutos hasta dorar ligeramente. Agrega el licuado de jitomate y cocina 2 minutos. Añade 2 tazas de agua, la zanahoria y el chícharo, cocina a fuego medio 10 minutos, hasta que el fideo y las verduras estén suaves. Una persona adulta debe supervisar el manejo del aceite caliente.'),
  (E'R52', E'Huevo tibio con tortilla y frijol', E'cena', E'6 a 8 años', E'Alimentos de origen animal + Leguminosas + Cereales', E'Huevo (1 pieza); Frijol refrito (3 cucharadas); Tortilla de maíz (1 pieza)', E'Alimentos de origen animal: 1; Leguminosas: 1; Cereales: 1', 265, 15, E'Una cena pequeña y sencilla, útil para niños con poco apetito por la noche.', E'Coloca el huevo con cáscara en agua hirviendo durante 6 minutos para que quede tibio (yema un poco líquida) o 9 minutos si se prefiere cocido por completo. Enfría un momento bajo el chorro de agua, pela y sirve junto con el frijol calentado y la tortilla. Una persona adulta debe manejar el agua hirviendo y pelar el huevo si está muy caliente.'),
  (E'R53', E'Palitos de zanahoria con hummus de garbanzo', E'colacion', E'9 a 12 años', E'Verduras + Leguminosas + Grasas', E'Zanahoria (1/2 taza, en bastones); Garbanzo cocido (1/4 taza); Limón (al gusto); Aceite de oliva (1 cucharadita)', E'Verduras: 1; Leguminosas: 1; Grasas: 1', 190, 10, E'El hummus casero sin mucha grasa es una forma de incluir leguminosa en una colación.', E'Licúa el garbanzo cocido con el limón, el aceite de oliva y un poco de agua hasta obtener una pasta tersa; agrega sal al gusto. Sirve en un plato pequeño acompañado de los bastones de zanahoria para remojar. Una persona adulta puede ayudar con la licuadora.'),
  (E'R54', E'Gelatina de fruta natural sin azúcar añadida', E'colacion', E'6 a 12 años', E'Frutas', E'Grenetina sin sabor (1 cucharadita); Jugo natural de fruta de temporada (1 taza); Fruta picada (1/4 taza)', E'Frutas: 1', 60, 15, E'Preparar la gelatina con jugo de fruta natural evita el azúcar añadida de las gelatinas comerciales.', E'Disuelve la grenetina en 2 cucharadas de agua fría y deja reposar 5 minutos. Calienta un poco del jugo de fruta (sin hervir) e incorpora la grenetina disuelta, moviendo hasta que no queden grumos. Mezcla con el resto del jugo frío y la fruta picada, vierte en un molde y refrigera al menos 2 horas, hasta que cuaje. Una persona adulta debe manejar el líquido caliente.'),
  (E'R55', E'Rebanadas de mango con chile piquín opcional', E'colacion', E'9 a 12 años', E'Frutas', E'Mango (1/2 pieza); Limón (al gusto); Chile piquín en polvo (opcional) (al gusto)', E'Frutas: 1', 60, 10, E'El mango es fruta de temporada en varias zonas de Puebla durante el verano.', E'Pela y corta el mango en rebanadas. Rocía con limón y, si al niño le gusta, un poco de chile piquín en polvo; esto es opcional y puede omitirse. No requiere cocción. Una persona adulta debe supervisar el corte de la fruta.'),
  (E'R56', E'Quesillo con totopos horneados', E'colacion', E'9 a 12 años', E'Alimentos de origen animal + Cereales', E'Queso Oaxaca o quesillo (30 gramos); Tortilla de maíz (1 pieza, en triángulos y horneada)', E'Alimentos de origen animal: 1; Cereales: 1', 170, 15, E'Hornear la tortilla en vez de freírla reduce la grasa añadida de los totopos.', E'Corta la tortilla en triángulos y hornea a 180°C de 8 a 10 minutos, volteando a la mitad, hasta que estén crujientes. Deshebra el quesillo y sirve junto con los totopos horneados. Una persona adulta debe manejar el horno.'),
  (E'R57', E'Paleta de yogur y fruta congelada', E'colacion', E'6 a 12 años', E'Leche y sustitutos + Frutas', E'Yogur natural sin azúcar (1/2 taza); Fruta de temporada (1/4 taza, picada)', E'Leche y sustitutos: 1; Frutas: 1', 155, 10, E'Una colación fría y refrescante, buena opción en temporada de calor.', E'Mezcla el yogur con la fruta picada. Vierte en moldes de paleta y congela al menos 4 horas, hasta que esté completamente firme. Desmolda pasando el molde un momento bajo agua tibia si no sale fácilmente. Una persona adulta debe ayudar a manipular el congelador.'),
  (E'R58', E'Pepino con limón y un poco de queso fresco', E'colacion', E'6 a 12 años', E'Verduras + Alimentos de origen animal', E'Pepino (1 taza, en rodajas); Queso fresco (2 cucharadas, desmoronado); Limón (al gusto)', E'Verduras: 1; Alimentos de origen animal: 1', 80, 10, E'Una colación fresca que combina verdura con una pequeña porción de alimento de origen animal.', E'Corta el pepino en rodajas y acomódalo en un plato. Espolvorea el queso desmoronado y rocía con limón al gusto justo antes de servir. No requiere cocción. Una persona adulta debe supervisar el corte.'),
  (E'R59', E'Sopa de verduras con pechuga deshebrada, sin cereal añadido', E'comida', E'9 a 12 años', E'Alimentos de origen animal + Verduras', E'Pechuga de pollo (80 gramos, cocida y deshebrada); Calabacita (1/4 taza); Zanahoria (1/4 taza); Chayote (1/4 taza); Cilantro (al gusto)', E'Alimentos de origen animal: 2; Verduras: 2', 160, 25, E'Esta sopa no lleva cereal porque ya se incluye en otro tiempo de comida del día, no para restringir calorías.', E'Cuece la calabacita, la zanahoria y el chayote en agua con un poco de sal durante 15 minutos, hasta que estén suaves. Agrega la pechuga ya cocida y deshebrada, calienta 3 minutos más. Sirve con cilantro picado encima. El ajuste de cereal se hace a lo largo del día, nunca eliminándolo por completo del menú del niño; esto debe acordarse siempre con el especialista que lleva el caso. Una persona adulta debe supervisar la cocción.'),
  (E'R60', E'Pollo a la plancha con ensalada de nopal sin grasa añadida', E'comida', E'9 a 12 años', E'Alimentos de origen animal + Verduras', E'Pechuga de pollo (100 gramos); Nopal (1/2 taza, cocido); Jitomate (1/4 pieza); Cebolla morada (1 cucharada); Limón (al gusto)', E'Alimentos de origen animal: 2; Verduras: 2', 160, 25, E'Se evita el aceite añadido en este plato, sin que eso signifique que el niño deba comer menos de lo que necesita.', E'Sazona la pechuga con sal y limón, cocina en una plancha o sartén sin aceite (o con un mínimo spray) de 5 a 6 minutos por lado, hasta que esté bien cocida por dentro. Mezcla el nopal cocido con el jitomate y la cebolla morada, aliña con limón. Sirve el pollo junto con la ensalada de nopal. Una persona adulta debe verificar que el pollo esté completamente cocido.'),
  (E'R61', E'Agua de jamaica sin azúcar con un toque de stevia natural', E'colacion', E'9 a 12 años', E'', E'Flor de jamaica (2 cucharadas); Agua natural (2 tazas); Hoja de stevia natural (opcional) (al gusto)', E'', 0, 15, E'Esta agua no lleva azúcar añadida; puede servirse sola o con un endulzante natural si el especialista lo autoriza.', E'Hierve la flor de jamaica en el agua durante 5 minutos. Retira del fuego, deja enfriar y cuela. Si se desea, endulza con hojas de stevia natural al gusto, nunca con azúcar de mesa en estos casos. Consulta siempre con el especialista qué endulzante es adecuado para el niño. Una persona adulta debe manejar el agua caliente.'),
  (E'R62', E'Yogur natural con semillas y fruta baja en azúcar', E'desayuno', E'9 a 12 años', E'Leche y sustitutos + Frutas + Grasas', E'Yogur natural sin azúcar (1 taza); Fresa o manzana verde (1/2 taza, picada); Semillas de chía (1 cucharadita)', E'Leche y sustitutos: 1; Frutas: 1; Grasas: 1', 200, 10, E'Se eligen frutas con menor contenido de azúcar natural, siempre dentro de un menú variado y no restrictivo.', E'Mezcla el yogur con la fruta picada y las semillas de chía. Deja reposar 5 minutos para que la chía se suavice un poco antes de servir. No requiere cocción.'),
  (E'R63', E'Tacos de canasta sencillos de papa con queso', E'comida', E'9 a 12 años', E'Cereales + Alimentos de origen animal + Grasas', E'Tortilla de maíz (3 piezas); Papa (1/2 taza, cocida y machacada); Queso fresco (20 gramos); Aceite vegetal (1 cucharadita)', E'Cereales: 3; Alimentos de origen animal: 1; Grasas: 1', 310, 25, E'Una versión casera y con poco aceite de un antojito tradicional mexicano.', E'Mezcla la papa machacada con el queso desmoronado. Rellena cada tortilla con la mezcla y dobla por la mitad. Calienta el aceite en un sartén y cocina los tacos por ambos lados a fuego medio, 2 minutos por lado, hasta que estén calientes y ligeramente dorados. Una persona adulta debe supervisar el manejo del aceite caliente.'),
  (E'R64', E'Chalupas poblanas con pollo y salsa suave', E'comida', E'9 a 12 años', E'Cereales + Alimentos de origen animal + Verduras', E'Tortilla pequeña de maíz (3 piezas); Pollo cocido deshebrado (60 gramos); Salsa roja suave (2 cucharadas); Cebolla (1 cucharada, picada)', E'Cereales: 3; Alimentos de origen animal: 1; Verduras: 1', 290, 20, E'Las chalupas son un antojito típico de Puebla; esta versión usa poco aceite para freír la tortilla.', E'Calienta las tortillas en comal con muy poco aceite por ambos lados hasta que estén firmes, sin que lleguen a freírse completamente. Unta un poco de salsa sobre cada una, agrega el pollo deshebrado y la cebolla picada encima. Sirve de inmediato. Una persona adulta debe supervisar el manejo del comal y el aceite.'),
  (E'R65', E'Ensalada de frutas de temporada con limón y chía', E'colacion', E'6 a 12 años', E'Frutas', E'Fruta mixta de temporada (1 taza, picada); Limón (al gusto); Semillas de chía (1 cucharadita)', E'Frutas: 1', 60, 10, E'Combinar varias frutas de temporada ayuda a variar sabores y texturas sin azúcar añadida.', E'Pica la fruta de temporada en trozos pequeños y mézclala en un tazón. Rocía con limón y espolvorea las semillas de chía encima. Deja reposar 5 minutos antes de servir. No requiere cocción.'),
  (E'R66', E'Arroz con leche ligero y canela', E'colacion', E'6 a 12 años', E'Cereales + Leche y sustitutos + Azúcares', E'Arroz blanco (1/4 taza, cocido); Leche descremada (1/2 taza); Canela en polvo (al gusto); Piloncillo o azúcar (1 cucharadita)', E'Cereales: 1; Leche y sustitutos: 1; Azúcares: 1', 205, 20, E'Una versión con menos azúcar que la receta tradicional, usando leche descremada.', E'En una olla pequeña, calienta la leche con el arroz ya cocido y la canela a fuego bajo, moviendo con frecuencia durante 8 a 10 minutos hasta que espese un poco. Agrega el piloncillo al final y retira del fuego. Deja entibiar antes de servir. Una persona adulta debe manejar la olla caliente.'),
  (E'R67', E'Burritos sencillos de frijol y queso', E'desayuno', E'9 a 12 años', E'Cereales + Leguminosas + Alimentos de origen animal', E'Tortilla de harina (1 pieza); Frijol refrito (3 cucharadas); Queso fresco (20 gramos)', E'Cereales: 1; Leguminosas: 1; Alimentos de origen animal: 1', 290, 10, E'Una opción rápida para llevar a la escuela en la lonchera.', E'Calienta la tortilla de harina ligeramente en comal, 30 segundos por lado. Unta el frijol refrito, agrega el queso desmoronado, enrolla bien apretado y envuelve en papel aluminio o encerado si se va a llevar de lonchera. Una persona adulta debe supervisar el calentado de la tortilla.'),
  (E'R68', E'Ensalada de pepino, jícama y naranja', E'colacion', E'9 a 12 años', E'Verduras + Frutas', E'Pepino (1/4 taza); Jícama (1/4 taza); Naranja (1/2 pieza, en gajos); Limón (al gusto); Chile piquín (opcional) (al gusto)', E'Verduras: 1; Frutas: 1', 85, 10, E'Combina verdura y fruta de forma fresca, típica de los puestos de la región en días calurosos.', E'Corta el pepino y la jícama en bastones o cubos pequeños, mezcla con los gajos de naranja. Rocía con limón y, si se desea, un poco de chile piquín (opcional, puede omitirse). No requiere cocción. Una persona adulta debe supervisar el corte.'),
  (E'R69', E'Omelette de verduras de la milpa', E'desayuno', E'9 a 12 años', E'Alimentos de origen animal + Verduras + Cereales', E'Huevo (1 pieza); Calabacita (1/4 taza, en cubos pequeños); Jitomate (1/4 pieza); Cebolla (1 cucharada); Tortilla de maíz (2 piezas)', E'Alimentos de origen animal: 1; Verduras: 1; Cereales: 2', 240, 20, E'El omelette es una forma versátil de incluir distintas verduras según la temporada.', E'Sofríe la calabacita, el jitomate y la cebolla en un sartén con un mínimo de aceite durante 4 minutos, hasta que estén suaves. Vierte el huevo batido encima, cocina a fuego bajo sin mover hasta que la base cuaje, después dobla a la mitad con ayuda de una espátula. Cocina 1 minuto más y sirve con las tortillas. Una persona adulta debe supervisar el manejo del huevo y el fuego.'),
  (E'R70', E'Caldo tlalpeño sencillo con pollo y garbanzo', E'comida', E'9 a 12 años', E'Alimentos de origen animal + Leguminosas + Verduras + Cereales', E'Pollo con hueso (100 gramos); Garbanzo cocido (1/4 taza); Zanahoria (1/4 taza); Chile chipotle (opcional, muy poco) (al gusto); Arroz blanco (2 cucharadas, cocido)', E'Alimentos de origen animal: 2; Leguminosas: 1; Verduras: 1; Cereales: 1', 325, 45, E'Una versión suave de este caldo tradicional, reduciendo el chipotle para que no pique fuerte.', E'Cuece el pollo en agua con sal durante 25 minutos. Agrega la zanahoria en cubos y cocina 10 minutos más. Incorpora el garbanzo cocido y, si se desea, una pizca muy pequeña de chipotle sin semillas, cocina 5 minutos adicionales. Retira los huesos antes de servir y acompaña con el arroz. Prueba el caldo antes de dar al niño para confirmar que no quede picante. Una persona adulta debe retirar huesos y verificar la cocción del pollo.'),
  (E'R71', E'Tostadas de nopal y queso sin frijol', E'cena', E'9 a 12 años', E'Cereales + Verduras + Alimentos de origen animal', E'Tostada horneada (2 piezas); Nopal (1/2 taza, cocido y picado); Queso fresco (20 gramos); Jitomate (1/4 pieza)', E'Cereales: 2; Verduras: 1; Alimentos de origen animal: 1', 220, 10, E'Una variación de las tostadas tradicionales usando nopal en lugar de frijol.', E'Mezcla el nopal picado con el jitomate en cubos. Reparte sobre las tostadas horneadas y corona con el queso desmoronado. Sirve de inmediato para que la tostada no se humedezca. No requiere cocción adicional.'),
  (E'R72', E'Pechuga empapelada con verduras al vapor', E'cena', E'9 a 12 años', E'Alimentos de origen animal + Verduras', E'Pechuga de pollo (80 gramos); Calabacita (1/4 taza); Zanahoria (1/4 taza); Limón (al gusto)', E'Alimentos de origen animal: 2; Verduras: 1', 135, 30, E'Cocinar envuelto en papel conserva los jugos del pollo sin necesidad de aceite añadido.', E'Coloca la pechuga y las verduras en rebanadas sobre un trozo de papel aluminio, agrega limón y sal, cierra bien el paquete. Hornea a 200°C durante 20 a 25 minutos, hasta que el pollo esté bien cocido. Abre el paquete con cuidado, pues sale vapor caliente. Una persona adulta debe manejar el horno y abrir el paquete.'),
  (E'R73', E'Atole de avena con canela', E'desayuno', E'6 a 12 años', E'Cereales + Leche y sustitutos + Azúcares', E'Avena en hojuelas (3 cucharadas); Leche de vaca (1 taza); Canela en polvo (al gusto); Piloncillo o azúcar (1 cucharadita)', E'Cereales: 1; Leche y sustitutos: 1; Azúcares: 1', 260, 20, E'Una variante del atole tradicional usando avena en lugar de masa de maíz.', E'Licúa la avena con un poco de la leche hasta que quede más fina. En una olla, calienta el resto de la leche con la canela, agrega la avena licuada y cocina a fuego bajo, moviendo con frecuencia, de 6 a 8 minutos hasta que espese. Agrega el piloncillo al final. Deja entibiar antes de servir. Una persona adulta debe manejar la olla caliente.'),
  (E'R74', E'Ensalada de lentejas con elote y jitomate', E'comida', E'9 a 12 años', E'Leguminosas + Cereales + Verduras', E'Lenteja (1/2 taza, cocida); Elote (1/4 taza, desgranado y cocido); Jitomate (1/4 pieza); Cilantro (al gusto); Limón (al gusto)', E'Leguminosas: 1; Cereales: 1; Verduras: 1', 215, 15, E'Una ensalada fría que aprovecha la lenteja ya cocida de otro día.', E'Mezcla la lenteja, el elote y el jitomate picado en un tazón. Agrega cilantro picado y limón al gusto. Sirve fría o a temperatura ambiente. No requiere cocción adicional si los ingredientes ya están cocidos. Una persona adulta debe supervisar el picado de los ingredientes.'),
  (E'R75', E'Papa al horno con queso y verdolagas', E'cena', E'9 a 12 años', E'Cereales + Alimentos de origen animal + Verduras', E'Papa (1 pieza mediana); Queso fresco (20 gramos); Verdolaga (1/2 taza, cocida)', E'Cereales: 1; Alimentos de origen animal: 1; Verduras: 1', 195, 55, E'Hornear la papa entera conserva más nutrientes que freírla.', E'Lava bien la papa y pícala varias veces con un tenedor. Hornea a 200°C durante 45 a 50 minutos, hasta que esté suave al picarla con un cuchillo. Corta por la mitad, abre un poco con un tenedor y rellena con el queso desmoronado y las verdolagas cocidas. Una persona adulta debe manejar el horno y cortar la papa caliente.'),
  (E'R76', E'Sopa de calabaza con garbanzo', E'comida', E'6 a 12 años', E'Verduras + Leguminosas + Cereales', E'Calabaza o calabacita (1 taza); Garbanzo cocido (1/4 taza); Cebolla (1 cucharada); Tortilla de maíz (2 piezas)', E'Verduras: 1; Leguminosas: 1; Cereales: 2', 285, 25, E'Combina verdura y leguminosa en un mismo plato caliente, fácil de preparar entre semana.', E'En una olla, sofríe la cebolla 2 minutos, agrega la calabaza en cubos y 2 tazas de agua, cocina 12 minutos hasta que esté suave. Incorpora el garbanzo cocido y cocina 5 minutos más. Sirve caliente con las tortillas. Una persona adulta debe supervisar el manejo de la olla caliente.'),
  (E'R77', E'Yuca cocida con queso y limón', E'colacion', E'9 a 12 años', E'Cereales + Alimentos de origen animal', E'Yuca (1/2 taza, cocida); Queso fresco (2 cucharadas, desmoronado); Limón (al gusto)', E'Cereales: 1; Alimentos de origen animal: 1', 125, 35, E'La yuca es un tubérculo que también se cultiva en algunas zonas cálidas de Puebla.', E'Si la yuca no está cocida, hiérvela en agua con sal durante 20 a 25 minutos, hasta que esté suave y se pueda atravesar fácilmente con un tenedor. Escurre, deja entibiar un poco, corona con el queso desmoronado y unas gotas de limón. Una persona adulta debe supervisar la cocción y el manejo de la olla caliente.'),
  (E'R78', E'Pan tostado con aguacate y huevo cocido', E'desayuno', E'9 a 12 años', E'Cereales + Grasas + Alimentos de origen animal', E'Pan integral o bolillo (1 pieza); Aguacate (1/4 pieza); Huevo (1/2 pieza, cocido); Limón (al gusto)', E'Cereales: 1; Grasas: 1; Alimentos de origen animal: 1', 215, 15, E'El aguacate aporta grasas saludables y se cultiva en varias zonas de la región.', E'Tuesta ligeramente el pan. Machaca el aguacate con un tenedor y unta sobre el pan, agrega unas gotas de limón. Corta el huevo cocido en rebanadas y colócalo encima. Sirve de inmediato. Una persona adulta debe supervisar la cocción del huevo si aún no está listo.');


insert into public.recetas (
  nombre_platillo, instrucciones, prep_horas, prep_minutos, calorias_porcion
)
select
  source.nombre_platillo,
  source.preparacion_completa,
  source.tiempo_preparacion_min / 60,
  source.tiempo_preparacion_min % 60,
  source.calorias_porcion_kcal
from recipe_source source
where not exists (
  select 1
  from public.recetas existing
  where lower(regexp_replace(btrim(existing.nombre_platillo), '[[:space:]]+', ' ', 'g')) =
    lower(regexp_replace(btrim(source.nombre_platillo), '[[:space:]]+', ' ', 'g'))
);

insert into public.catalogo_recetas_warrior_kids (
  codigo, id_receta, nombre_platillo, tipo_comida, grupo_edad, combinacion_grupos,
  ingredientes, porciones_por_grupo, calorias_porcion_kcal, tiempo_preparacion_min,
  nota_educativa_app, preparacion_completa
)
select
  source.codigo,
  recipe.id_receta,
  source.nombre_platillo,
  source.tipo_comida,
  source.grupo_edad,
  source.combinacion_grupos,
  source.ingredientes,
  source.porciones_por_grupo,
  source.calorias_porcion_kcal,
  source.tiempo_preparacion_min,
  source.nota_educativa_app,
  source.preparacion_completa
from recipe_source source
join lateral (
  select existing.id_receta
  from public.recetas existing
  where lower(regexp_replace(btrim(existing.nombre_platillo), '[[:space:]]+', ' ', 'g')) =
    lower(regexp_replace(btrim(source.nombre_platillo), '[[:space:]]+', ' ', 'g'))
  order by existing.id_receta
  limit 1
) recipe on true
